import {normalize} from './engine.js';
export const localDate=(date=new Date())=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const months=['january','february','march','april','may','june','july','august','september','october','november','december'];const days=['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];
export function parseGameDate(raw,now=new Date()){let t=String(raw).toLowerCase().trim().replace(/[,.]/g,' ').replace(/\s+/g,' ');const relative=t.match(/\b(today|tomorrow|day after tomorrow)\b/);if(relative){const d=new Date(now);d.setDate(d.getDate()+(t.includes('day after tomorrow')?2:t.includes('tomorrow')?1:0));return localDate(d);}const weekday=days.findIndex(d=>new RegExp(`\\b${d}\\b`).test(t));if(weekday>=0&&!months.some(m=>t.includes(m))){const d=new Date(now);let delta=(weekday-d.getDay()+7)%7;if(delta===0||t.includes('next'))delta=delta||7;d.setDate(d.getDate()+delta);return localDate(d);}const ordinal={first:'one',second:'two',third:'three',fourth:'four',fifth:'five',sixth:'six',seventh:'seven',eighth:'eight',ninth:'nine',tenth:'ten',eleventh:'eleven',twelfth:'twelve',thirteenth:'thirteen',fourteenth:'fourteen',fifteenth:'fifteen',sixteenth:'sixteen',seventeenth:'seventeen',eighteenth:'eighteen',nineteenth:'nineteen',twentieth:'twenty',thirtieth:'thirty'};t=t.replace(/-/g,' ').replace(/\b(first|second|third|fourth|fifth|sixth|seventh|eighth|ninth|tenth|eleventh|twelfth|thirteenth|fourteenth|fifteenth|sixteenth|seventeenth|eighteenth|nineteenth|twentieth|thirtieth)\b/g,w=>ordinal[w]);t=normalize(t).replace(/(\d)(st|nd|rd|th)\b/g,'$1').replace(/\bthe\b/g,'');const mo=months.findIndex(m=>t.includes(m));if(mo<0)throw Error('Say a weekday, “tomorrow,” or a date such as “September 18, 2026.”');const rest=t.slice(t.indexOf(months[mo])+months[mo].length).trim(),match=rest.match(/^(\d{1,2})(?:\s+(\d{4}))?\b/);if(!match)throw Error('Include the day of the month, such as September 18.');let year=match[2]?+match[2]:now.getFullYear();const day=+match[1];let d=new Date(year,mo,day);if(d.getMonth()!==mo||d.getDate()!==day)throw Error('That date is not valid. Please check it.');if(!match[2]&&localDate(d)<localDate(now)){year++;d=new Date(year,mo,day);}return localDate(d);}
export function parseStartTime(raw){let t=String(raw).toLowerCase().replace(/\./g,'').replace(/\s+/g,' ').trim();if(/^(skip|none|no time|unknown|not sure|leave blank|dont know)$/.test(t))return '';if(/\bnoon\b/.test(t))return '12:00';if(/\bmidnight\b/.test(t))return '00:00';const pm=/\bpm\b|evening|afternoon|night/.test(t),am=/\bam\b|morning/.test(t);t=normalize(t).replace(/o clock|oclock/g,'').replace(/\b(?:starts? (?:at )?|at |around )/g,'').trim();const m=t.match(/\b(\d{1,2})(?::(\d{2})|\s+(\d{1,2}))?/);if(!m)throw Error('Say a time such as “7 PM” or leave the time blank.');let h=+m[1],min=+(m[2]||m[3]||0);if(min>59||h>23||((pm||am)&&h>12))throw Error('Check the start time.');if(!pm&&!am&&h>=1&&h<=12)throw Error('Say AM or PM, for example “7 PM.”');if(pm&&h<12)h+=12;if(am&&h===12)h=0;return `${String(h).padStart(2,'0')}:${String(min).padStart(2,'0')}`;}
export const opponentFromSpeech=s=>String(s).trim().replace(/^(?:we(?:re| are)?\s+|i(?:m| am)?\s+)?(?:playing|play|against|opponent is)\s+/i,'').replace(/[.!]+$/,'').trim();
export function scheduleLabel(meta={}){let label='Date not set';if(meta.date){const [y,m,d]=meta.date.split('-').map(Number);label=new Intl.DateTimeFormat(undefined,{weekday:'short',month:'short',day:'numeric',year:'numeric'}).format(new Date(y,m-1,d));}if(meta.startTime){const [h,m]=meta.startTime.split(':').map(Number);label+=' · '+new Intl.DateTimeFormat(undefined,{hour:'numeric',minute:'2-digit'}).format(new Date(2000,0,1,h,m));}return label;}
